package darkrpg.tweaks.compat.pvp.mixin;

import net.minecraft.class_1282;
import net.minecraft.class_1657;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

/**
 * Prevent More RPG Library 2.7.2 damage reflection endlessly bouncing between
 * two players. The first reflected damage is preserved. The second reflection
 * generated by the same active call chain is rejected before player damage,
 * Origins/Apoli powers, or other damage handlers are invoked again.
 *
 * This is restricted to DIRECT player-to-player damage. The StackWalker check
 * is an observation of the current synchronous call chain; it does not store
 * global state, alter attributes, or leak guards across players or ticks.
 */
@Mixin(targets = "net.minecraft.class_1309", remap = false)
public abstract class PvPReflectionLoopGuardMixin {
    private static final String DARKRPG_TWEAKS_REFLECTION_HANDLER = "more_rpg_classes$damageReflect$damage";

    @Inject(
        method = "method_5643(Lnet/minecraft/class_1282;F)Z",
        at = @At(value = "HEAD", remap = false),
        cancellable = true,
        remap = false,
        require = 1
    )
    private void darkrpgtweaks$stopRecursivePvPReflection(class_1282 source, float amount,
            CallbackInfoReturnable<Boolean> cir) {
        // Keep the guard narrowly scoped to direct player-vs-player damage.
        if (!(((Object) this) instanceof class_1657) ||
                !(source.method_5529() instanceof class_1657 attacker) ||
                source.method_5526() != attacker || amount <= 0.0F) {
            return;
        }

        if (darkrpgtweaks$secondReflectionAlreadyInFlight()) {
            cir.setReturnValue(Boolean.FALSE);
        }
    }

    private static boolean darkrpgtweaks$secondReflectionAlreadyInFlight() {
        // Two nested calls to the *specific* More RPG damage-reflect handler
        // means the first reflected hit is being reflected again. Blocking here
        // avoids both recursion and modifications to normal attack semantics.
        return StackWalker.getInstance().walk(frames ->
            frames.filter(frame -> frame.getMethodName().contains(DARKRPG_TWEAKS_REFLECTION_HANDLER))
                .limit(2)
                .count() >= 2L);
    }
}
